// Waitlist intake — accepts early-access signups from the PWA.
//
// Per Darrell 2026-05-28 evening + GOVERNANCE-EXECUTION-ADVISORY:
// marketing surfaces follow pipeline readiness. The waitlist IS the intake
// pipeline for 'I'm interested.' Without it, advertising creates demand
// without capture. With it, Darrell can activate engagements based on
// opportunities + capacity, not pressure.
//
// POST body shape:
//   { name, email, phone?, interest?, notes?, source? }
// All fields except email are optional. Validation is light — bad data
// gets stored with a flag, not rejected, since dropped leads are worse
// than messy ones.
//
// Per AI-FOUNDATION-INTERNAL-OPERATIONS: this becomes a Foundation
// surface. The briefing endpoint (workflow 23) can surface waitlist
// counts. A future workflow can categorize signups by persona, prioritize
// by Foundation's anxiety-clarity criteria, and queue outreach for
// Governor review.

const fs = require('fs');
const path = require('path');
const http = require('http');

const WAITLIST_DIR = '/data/waitlist';
const NTFY_HOST = process.env.NTFY_HOST || 'ntfy';
const NTFY_PORT = parseInt(process.env.NTFY_PORT || '80', 10);
const NTFY_TOPIC = process.env.NTFY_WAITLIST_TOPIC || 'poetech-waitlist';

try { fs.mkdirSync(WAITLIST_DIR, { recursive: true }); } catch (_) {}

const input = $input.first().json || {};
const body = (input.body && typeof input.body === 'object') ? input.body : input;

const email = (body.email || '').toString().trim().toLowerCase();
const name = (body.name || '').toString().trim();
const phone = (body.phone || '').toString().trim();
const interest = (body.interest || '').toString().trim();
const notes = (body.notes || '').toString().trim();
const source = (body.source || 'poetech.us').toString().trim();

// Light validation — email shape only. Don't be strict; messy leads beat
// dropped leads.
function looksLikeEmail(s) {
  return /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(s);
}
const emailValid = looksLikeEmail(email);
if (!email) {
  return [{ json: { ok: false, error: 'email is required' } }];
}

const capturedAt = new Date().toISOString();
const id = 'wl-' + capturedAt.replace(/[:.]/g, '-') + '-' + Math.floor(Math.random() * 10000);
const record = {
  id,
  captured_at: capturedAt,
  name,
  email,
  email_valid: emailValid,
  phone,
  interest,
  notes,
  source,
  status: 'new',
  governor_action: null,
  governor_action_at: null,
};

const safeFn = id + '.json';
try { fs.writeFileSync(path.join(WAITLIST_DIR, safeFn), JSON.stringify(record, null, 2)); }
catch (e) { return [{ json: { ok: false, error: 'write failed: ' + String(e) } }]; }

function pushNtfy(title, bodyText) {
  return new Promise(resolve => {
    const opts = {
      host: NTFY_HOST, port: NTFY_PORT, path: '/' + NTFY_TOPIC, method: 'POST',
      headers: {
        'Title': title, 'Priority': '4',
        'Tags': 'envelope_with_arrow',
        'Content-Type': 'text/plain'
      }, timeout: 5000
    };
    const req = http.request(opts, res => resolve({ ok: res.statusCode < 400 }));
    req.on('error', () => resolve({ ok: false }));
    req.on('timeout', () => { req.destroy(); resolve({ ok: false }); });
    req.write(bodyText);
    req.end();
  });
}

const preview = [name || '(no name)', email, interest && '· ' + interest, notes && '· ' + notes.slice(0, 100)].filter(Boolean).join(' ');
(async () => { try { await pushNtfy('PoeTech waitlist · new signup', preview); } catch (_) {} })();

return [{ json: { ok: true, id, captured_at: capturedAt, message: 'Thanks — added to the waitlist. We will be in touch.' } }];
